arguments.new_str:
using System.IO.Compression;
using System.Text;

class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipFile now always writes UTF-8 with the EFS
        // flag set, ignoring non-UTF-8 entry name encodings. Explicitly specify
        // Shift-JIS so the legacy Java consumer can read the filenames.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: DI validation now rejects [FromKeyedServices]
// when the service is registered as non-keyed. Register with a key.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

